-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Fundamentos de UI / UX' and a.numero = 4
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 04 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 04', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 04 (20 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/FUNDAMENTOS-DE-UI-UX/ATIVIDADES/ATIVIDADE-PRATICA-AULA-04.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Defina gosto pessoal e explique por que ele não aponta a causa de um erro na tarefa.', 0.2, 'Gosto pessoal é a opinião subjetiva e individual, baseada em sentimentos e preferências, sem fundamentação. Ele não aponta a causa do erro, porque não descreve nenhum comportamento da tela que impeça a tarefa.', 'Nota cheia: define gosto pessoal como subjetivo ou opinativo e explica que ele não identifica a causa do erro na tarefa. Metade: define corretamente, mas não explica a relação com a causa do erro, ou o contrário. Zero: em branco, define como fato verificável, ou fora do tema.'),
      (v_atividade, 1, 2, 'Defina crítica técnica e dê um exemplo verificável, com medida ou regra visual.', 0.4, 'Crítica técnica é a avaliação fundamentada em regras objetivas e medições, verificáveis por qualquer pessoa. Exemplo válido: "o texto lilás tem contraste 1.8:1, abaixo da norma de 4.5:1".', 'Nota cheia: define crítica técnica como avaliação com base em regra ou medida e dá um exemplo verificável com número ou regra visual. Metade: define corretamente, mas o exemplo é vago (ex.: "a cor está ruim") ou não é verificável. Zero: em branco, exemplo de gosto pessoal, ou fora do tema.'),
      (v_atividade, 1, 3, 'Explique por que uma crítica técnica permite propor uma correção clara.', 0.4, 'Uma crítica técnica informa a medida que está fora do padrão, e por isso indica o valor exato a alcançar. Assim a equipe sabe o que alterar e como conferir o resultado depois da correção.', 'Nota cheia: explica que a crítica técnica aponta a causa verificável e que, por isso, permite propor uma correção clara, com um valor de referência. Metade: afirma que ela "ajuda a corrigir" sem explicar a relação com a medida ou a regra. Zero: em branco, afirma que a correção depende de opinião, ou fora do tema.'),
      (v_atividade, 2, 1, 'Descreva o que é um fato objetivo e dê um exemplo de fato sobre a tela desta queixa.', 0.2, 'Fato objetivo é o que está visivelmente ocorrendo na tela, sem julgamento. Exemplo sobre a queixa: "ao tocar no botão errado, o formulário apaga os dados já preenchidos".', 'Nota cheia: define fato objetivo como algo observável, sem julgamento, e dá um exemplo sobre a tela da queixa. Metade: define corretamente, mas o exemplo é genérico ou não se refere à queixa. Zero: em branco, exemplo de opinião ou de causa, ou fora do tema.'),
      (v_atividade, 2, 2, 'Descreva a causa técnica e explique como ela se diferencia do fato.', 0.4, 'A causa técnica é a decisão de projeto que provocou a condição, como um botão de ação posicionado perto de outro, sem proteção ou confirmação. Ela se diferencia do fato porque o fato é o que se vê, e a causa é a decisão por trás do que se vê.', 'Nota cheia: descreve causa técnica como decisão de projeto ou regra violada e explica a diferença em relação ao fato (o que se vê × o que provocou). Metade: descreve a causa, mas a diferença fica confusa ou ausente. Zero: em branco, descreve o fato no lugar da causa, ou fora do tema.'),
      (v_atividade, 2, 3, 'Descreva o efeito prático sentido pelo usuário.', 0.4, 'O efeito prático é o impacto concreto sentido pelo usuário: ele perde os dados preenchidos, precisa digitar tudo de novo e pode desistir do formulário.', 'Nota cheia: descreve o efeito sentido pela pessoa usuária (perda de dados, retrabalho, frustração ou desistência) com as próprias palavras. Metade: cita apenas um efeito sem relação com a tarefa, ou descreve a causa em vez do efeito. Zero: em branco, fora do tema, ou copiado sem adaptação.'),
      (v_atividade, 3, 1, 'Explique por que a frase é um julgamento e não um fato.', 0.2, 'A frase é um julgamento porque afirma a intenção ou o pensamento do desenvolvedor, algo que não se pode observar nem medir na tela.', 'Nota cheia: explica que a frase afirma algo sobre a intenção ou o pensamento de alguém, que não é observável na tela. Metade: diz apenas que "é uma opinião" ou "não é verdade", sem o motivo. Zero: em branco, classifica a frase como fato, ou fora do tema.'),
      (v_atividade, 3, 2, 'Explique o que significa dizer que um fato é "a realidade física da tela que independe de interpretação pessoal".', 0.4, 'Dizer que o fato é a realidade física da tela significa que ele existe no próprio objeto (tamanho, posição, cor) e continua o mesmo para qualquer pessoa que o examine, independentemente da opinião de quem olha.', 'Nota cheia: explica que o fato existe na tela e não depende de interpretação, e que qualquer pessoa pode confirmá-lo. Metade: explica de forma parcial, sem ligar à confirmação por terceiros. Zero: em branco, ou explica como opinião, ou fora do tema.'),
      (v_atividade, 3, 3, 'Reescreva a frase como um fato objetivo que qualquer pessoa possa medir e confirmar.', 0.4, 'Uma reescrita válida descreve um elemento mensurável, por exemplo: "o botão de confirmação mede 24 por 24 pixels e fica no canto inferior, sem rótulo de texto".', 'Nota cheia: reescreve a frase como fato observável, com medida ou posição que qualquer pessoa possa conferir, sem julgar pessoas. Metade: reescreve como fato, mas sem medida ou posição verificável. Zero: em branco, mantém o julgamento sobre a intenção do desenvolvedor, ou fora do tema.'),
      (v_atividade, 4, 1, 'Liste os quatro passos do método na ordem correta.', 0.2, 'A ordem correta é: 1) identificar o fato objetivo visível na tela; 2) investigar a causa técnica de design; 3) mapear o efeito prático na pessoa usuária; 4) propor a recomendação técnica de melhoria.', 'Nota cheia: lista os quatro passos na ordem exata (fato, causa, efeito, recomendação). Metade: lista três passos na ordem certa, ou os quatro com uma troca entre dois passos. Zero: em branco, ordem invertida ou embaralhada, ou fora do tema.'),
      (v_atividade, 4, 2, 'Explique por que a identificação do fato vem antes da investigação da causa técnica.', 0.4, 'O fato vem antes porque a causa só pode ser investigada depois que o fato estiver descrito com precisão. Sem o fato, a investigação se apoia em suposições, e o diagnóstico pode apontar a causa errada.', 'Nota cheia: explica que a causa depende de um fato bem definido e que, sem ele, a análise vira suposição. Metade: explica apenas que "é a ordem do método", sem justificar. Zero: em branco, ou justificativa que contraria o método, ou fora do tema.'),
      (v_atividade, 4, 3, 'Explique o que se perde quando a recomendação é feita antes do efeito prático ser mapeado.', 0.4, 'Ao pular o mapeamento do efeito prático, perde-se a medida da gravidade do problema, e a recomendação pode resolver um detalhe sem atacar o que mais prejudica a pessoa usuária.', 'Nota cheia: explica que sem o efeito mapeado não se sabe a gravidade nem o impacto real, e a recomendação pode ficar desalinhada com o problema. Metade: diz apenas que "a recomendação fica incompleta", sem explicar o impacto. Zero: em branco, ou fora do tema.'),
      (v_atividade, 5, 1, 'Associe os campos espalhados sem grade a uma causa técnica e explique a relação.', 0.2, 'Campos espalhados sem grade são um desalinhamento visual, causado pela falta de uma grade estruturada. Isso gera cansaço nos olhos, porque a pessoa precisa procurar o próximo dado sem uma ordem clara.', 'Nota cheia: associa campos sem grade a desalinhamento visual ou falta de grade estruturada e explica o cansaço ao buscar o próximo dado. Metade: associa à causa certa, mas sem explicar o efeito. Zero: em branco, associa a outra causa (ex.: contraste), ou fora do tema.'),
      (v_atividade, 5, 2, 'Associe os botões pequenos a uma causa técnica e explique o efeito no toque.', 0.4, 'Botões pequenos são a causa de área de toque minúscula, abaixo do mínimo de 44x44 pixels. O efeito no toque são cliques acidentais em outro elemento ou toques que não respondem.', 'Nota cheia: associa botões pequenos à área de toque abaixo de 44x44 px e explica o efeito de toques acidentais ou falta de resposta. Metade: associa a causa certa, mas sem o efeito no toque ou sem a medida. Zero: em branco, associa a outra causa, ou fora do tema.'),
      (v_atividade, 5, 3, 'Associe os títulos e botões com o mesmo peso visual a uma causa técnica e explique a competição pela atenção.', 0.4, 'Títulos e botões com o mesmo peso visual são a falta de hierarquia. Como todos competem pela atenção ao mesmo tempo, a pessoa não sabe qual elemento é o principal.', 'Nota cheia: associa títulos e botões de mesmo peso à falta de hierarquia visual e explica a competição pela atenção. Metade: associa à causa certa, sem explicar a competição pela atenção. Zero: em branco, associa a outra causa, ou fora do tema.'),
      (v_atividade, 6, 1, 'Descreva a sobrecarga cognitiva que a pessoa sofre nessa tela.', 0.2, 'A sobrecarga cognitiva acontece quando a pessoa gasta energia tentando entender onde clicar e o que os rótulos técnicos significam, em vez de focar na ação de pagamento.', 'Nota cheia: descreve a sobrecarga cognitiva como esforço mental para entender a tela (botão sem destaque, rótulos técnicos), com as próprias palavras. Metade: menciona a sobrecarga, mas sem relacionar com a tela descrita. Zero: em branco, ou descreve um erro operacional no lugar, ou fora do tema.'),
      (v_atividade, 6, 2, 'Descreva um erro operacional que pode acontecer e explique como ele surge.', 0.4, 'Um erro operacional possível é tocar em outro botão, ou em um elemento próximo, por engano, porque o botão de pagamento não tem destaque e se funde ao fundo. O erro surge da falta de destaque que guie o toque.', 'Nota cheia: descreve um erro concreto (toque em elemento errado, ação indesejada) e explica como ele surge a partir do botão sem destaque. Metade: descreve um erro, mas sem explicar a origem na interface. Zero: em branco, descreve sobrecarga no lugar do erro, ou fora do tema.'),
      (v_atividade, 6, 3, 'Explique como essa situação pode levar ao abandono da tarefa.', 0.4, 'Depois de sentir a sobrecarga e cometer erros, a pessoa se frustra e desiste de concluir a compra. O suporte recebe as reclamações de desistência porque a tarefa não foi concluída.', 'Nota cheia: liga a sobrecarga e os erros à desistência ou abandono da tarefa, com a frustração como elo. Metade: diz que "ela desiste", sem explicar o caminho. Zero: em branco, ou fora do tema.'),
      (v_atividade, 7, 1, 'Defina barreira de interação com as suas palavras.', 0.2, 'Barreira de interação é qualquer impedimento visual ou lógico que paralisa a pessoa usuária e a impede de concluir a tarefa.', 'Nota cheia: define barreira como impedimento visual ou lógico que paralisa a conclusão da tarefa, com as próprias palavras. Metade: define de forma parcial, como "um problema na tela", sem relação com a tarefa. Zero: em branco, ou define como ruído visual, ou fora do tema.'),
      (v_atividade, 7, 2, 'Diga a qual tipo de barreira essa situação pertence e explique por quê.', 0.4, 'A situação pertence à barreira do tipo "sem feedback": a tela não avisa se o envio funcionou, então a pessoa clica várias vezes sem saber o resultado.', 'Nota cheia: identifica a barreira "sem feedback" (ou falta de retorno visual) e justifica pela ausência de aviso após o clique. Metade: identifica a barreira, mas sem justificar com a situação descrita. Zero: em branco, identifica outra barreira sem justificativa, ou fora do tema.'),
      (v_atividade, 7, 3, 'Explique por que o defeito é do design e não do usuário, nesse caso.', 0.4, 'O defeito é do design porque a interface deixa de informar o estado do sistema. Quando um erro se repete em muitas pessoas, a causa está na tela, e não no comportamento do usuário.', 'Nota cheia: explica que a tela não informa o resultado, por isso a falha é de design, e que o usuário apenas reage ao que a interface mostra. Metade: diz que "é do design", sem justificar. Zero: em branco, culpa o usuário, ou fora do tema.'),
      (v_atividade, 8, 1, 'Defina ruído visual com as suas palavras.', 0.2, 'Ruído visual é o excesso de elementos gráficos desnecessários que disputam a atenção com a informação essencial, sobrecarregando e desorientando o olhar.', 'Nota cheia: define ruído visual como elementos desnecessários que disputam atenção com a informação essencial, com as próprias palavras. Metade: define de forma parcial, sem a ideia de disputa pela atenção. Zero: em branco, ou fora do tema.'),
      (v_atividade, 8, 2, 'Identifique as fontes de ruído presentes na tela (cores, bordas e avisos) e relacione cada uma ao problema.', 0.4, 'As fontes de ruído são: cores de destaque em excesso (cinco, acima do limite de quatro sem paleta), bordas grossas em todos os cartões, que fragmentam a visão, e avisos flutuantes que cobrem o formulário.', 'Nota cheia: identifica as três fontes (cores, bordas e avisos) e relaciona cada uma ao problema que causa. Metade: identifica duas fontes com a relação, ou três fontes sem a relação. Zero: em branco, ou identifica fontes que não existem na tela descrita, ou fora do tema.'),
      (v_atividade, 8, 3, 'Explique por que um elemento gráfico sem função disputa atenção com a informação essencial.', 0.4, 'Um elemento sem função ganha destaque visual sem ajudar a tarefa. Como ele chama o olhar, a informação essencial perde atenção e a pessoa tem mais dificuldade para encontrar o que precisa.', 'Nota cheia: explica que o elemento sem função chama atenção sem ajudar a tarefa, e que isso tira a atenção da informação essencial. Metade: diz que "polui a tela", sem explicar a disputa por atenção. Zero: em branco, ou fora do tema.'),
      (v_atividade, 9, 1, 'Classifique o desalinhamento na matriz de severidade e justifique.', 0.2, 'O desalinhamento é uma falha cosmética, porque é um pequeno problema visual que não impede a ação da pessoa.', 'Nota cheia: classifica como cosmética e justifica por não impedir a ação. Metade: classifica como cosmética, sem justificar, ou classifica como leve com justificativa correta. Zero: em branco, classifica como catastrófica ou grave sem justificativa, ou fora do tema.'),
      (v_atividade, 9, 2, 'Classifique o texto com contraste fraco e o botão inacessível, justificando cada escolha.', 0.4, 'O texto com contraste fraco é uma falha leve, porque atrasa a leitura sem bloquear a tarefa. O botão principal inacessível é catastrófico, porque a ação principal fica indisponível e bloqueia o uso total.', 'Nota cheia: classifica o contraste fraco como leve e o botão inacessível como catastrófico, justificando cada escolha pelo impacto. Metade: acerta uma das duas classificações com justificativa. Zero: em branco, classificações invertidas, ou fora do tema.'),
      (v_atividade, 9, 3, 'Monte a ordem de prioridade das três falhas, da mais urgente para a menos urgente.', 0.4, 'A ordem de prioridade é: 1) botão principal inacessível (catastrófica); 2) texto com contraste fraco (leve); 3) desalinhamento (cosmética).', 'Nota cheia: monta a ordem completa, do mais urgente ao menos urgente (botão, contraste, desalinhamento), com a relação com a gravidade. Metade: acerta o primeiro item e erra a ordem dos demais, ou acerta a ordem com um erro de posição. Zero: em branco, ordem invertida, ou fora do tema.'),
      (v_atividade, 10, 1, 'Explique por que o contraste entre texto e fundo é um fato mensurável.', 0.2, 'O contraste é um fato mensurável porque é uma razão numérica entre as luminâncias do texto e do fundo, que qualquer pessoa pode medir com um instrumento ou calculadora.', 'Nota cheia: explica que o contraste é uma medida numérica entre texto e fundo, que pode ser conferida por qualquer pessoa. Metade: diz que "é possível medir", sem explicar o que é medido. Zero: em branco, ou trata como opinião, ou fora do tema.'),
      (v_atividade, 10, 2, 'Explique a diferença entre um contraste insuficiente e um contraste adequado para leitura, segundo a aula.', 0.4, 'Contraste insuficiente é quando texto e fundo têm luminâncias próximas demais e a leitura fica lenta ou difícil. Contraste adequado é o que atinge o valor mínimo de referência da aula (4.5:1 para texto comum), permitindo leitura rápida.', 'Nota cheia: diferencia os dois casos e cita o valor de referência de 4.5:1 ou explica o critério de luminância próxima versus adequada. Metade: diferencia os casos sem citar o valor ou o critério. Zero: em branco, ou inverte os conceitos, ou fora do tema.'),
      (v_atividade, 10, 3, 'Escreva uma frase de melhoria baseada em um valor de contraste verificável.', 0.4, 'Uma frase válida de melhoria é: "O texto cinza claro sobre o cartão tem contraste de 2.1:1; sugiro elevar para 4.5:1, mantendo um tom mais escuro."', 'Nota cheia: escreve uma frase de melhoria com um valor de contraste verificável (medido e alvo) e uma ação concreta. Metade: sugere melhoria com o valor, mas sem o valor medido, ou o contrário. Zero: em branco, sugestão sem valor, ou fora do tema.'),
      (v_atividade, 11, 1, 'Diga qual é o fato objetivo sobre o tamanho e o espaçamento dos números.', 0.2, 'O fato objetivo é que os números dos dias medem 16 por 16 pixels e têm espaçamento zero entre si.', 'Nota cheia: descreve o tamanho (16x16 px) e o espaçamento zero como fatos. Metade: descreve apenas o tamanho ou apenas o espaçamento. Zero: em branco, fora do tema, ou afirma causa no lugar do fato.'),
      (v_atividade, 11, 2, 'Explique a causa técnica, relacionando o tamanho à área mínima de toque recomendada para telas móveis.', 0.4, 'A causa técnica é que o tamanho dos números desrespeita a área mínima de toque de 44x44 pixels recomendada para telas móveis. Por isso o dedo não consegue acertar a data com segurança.', 'Nota cheia: relaciona o tamanho de 16 px à área mínima de 44x44 px e explica por que o dedo erra. Metade: cita a norma sem relacionar com o tamanho descrito. Zero: em branco, ou fora do tema.'),
      (v_atividade, 11, 3, 'Explique o efeito prático e proponha uma melhoria com medida, como a indicada na aula.', 0.4, 'O efeito prático é que os usuários tocam em datas erradas e desistem do agendamento. Uma melhoria com medida é redimensionar os botões para 48 pixels e espaçar as datas em 8 pixels.', 'Nota cheia: descreve o efeito (toques em datas erradas, desistência) e propõe melhoria com medida (48 px e 8 px ou medida equivalente acima de 44x44 px). Metade: descreve o efeito e propõe melhoria sem medida. Zero: em branco, ou fora do tema.'),
      (v_atividade, 12, 1, 'Descreva o fato observado na tela, sem julgamento.', 0.2, 'O fato observado é que o botão Confirmar fica abaixo da dobra de rolagem e a tela não indica que é preciso rolar para encontrá-lo.', 'Nota cheia: descreve a posição do botão abaixo da dobra e a ausência de indicação de rolagem, sem julgamento. Metade: descreve apenas a posição ou apenas a ausência de indicação. Zero: em branco, com julgamento (ex.: "o app é ruim"), ou fora do tema.'),
      (v_atividade, 12, 2, 'Formule a hipótese de causa técnica, dizendo qual padrão de interação foi violado.', 0.4, 'A hipótese de causa técnica é que o padrão de visibilidade da ação principal foi violado: a ação primária não tem posicionamento fixo nem indicação visual de rolagem.', 'Nota cheia: formula a hipótese como violação de padrão de visibilidade ou de interação (ação primária sem posição fixa ou sem indicação de rolagem). Metade: diz que "o botão está mal posicionado", sem nomear o padrão. Zero: em branco, ou hipótese sobre o usuário, ou fora do tema.'),
      (v_atividade, 12, 3, 'Classifique a gravidade da falha e explique o efeito para a pessoa usuária.', 0.4, 'A falha é catastrófica, porque a ação principal fica inacessível e bloqueia o uso da tela. Para a pessoa usuária, parece que o aplicativo travou e ela abandona o agendamento.', 'Nota cheia: classifica como catastrófica, justifica pela ação principal inacessível e descreve o efeito (sensação de travamento, abandono). Metade: classifica corretamente, sem o efeito, ou classifica como grave com justificativa. Zero: em branco, classificação sem justificativa, ou fora do tema.'),
      (v_atividade, 13, 1, 'Explique o que é a identificação do componente e dê um exemplo para a tela de seleção de horário.', 0.2, 'A identificação do componente é o nome e a localização exata da tela. Exemplo: "tela de seleção de horário do agendamento, na etapa de escolher a hora".', 'Nota cheia: explica que é o nome e a localização exata da tela, e dá um exemplo para a tela de seleção de horário. Metade: explica a ideia, mas o exemplo é genérico. Zero: em branco, ou fora do tema.'),
      (v_atividade, 13, 2, 'Explique o que deve constar em "fato observado e gravidade" e por que a evidência precisa ser mensurável.', 0.4, 'O item "fato observado e gravidade" contém a descrição objetiva do que acontece na tela, com a classificação da gravidade. A evidência precisa ser mensurável para que qualquer pessoa da equipe possa conferir o diagnóstico.', 'Nota cheia: explica o conteúdo (descrição objetiva e gravidade) e justifica a evidência mensurável pela possibilidade de conferência. Metade: explica o conteúdo, sem justificar a evidência mensurável. Zero: em branco, ou descreve opinião como fato, ou fora do tema.'),
      (v_atividade, 13, 3, 'Explique a diferença entre "hipótese de causa técnica" e "proposta de melhoria".', 0.4, 'A hipótese de causa técnica diz qual regra visual ou padrão de interação foi violado. A proposta de melhoria diz a modificação prática que elimina a barreira sem quebrar o sistema.', 'Nota cheia: diferencia a hipótese (regra ou padrão violado) da proposta (modificação prática que elimina a barreira). Metade: diferencia, mas de forma pouco clara ou com um dos dois conceitos incompleto. Zero: em branco, ou inverte os conceitos, ou fora do tema.'),
      (v_atividade, 14, 1, 'Explique por que a abordagem agressiva gera atrito na equipe.', 0.2, 'A abordagem agressiva gera atrito porque ataca a pessoa e não a tela. Com isso, a equipe reage na defensiva, não explica onde está a falha e não propõe como resolvê-la.', 'Nota cheia: explica que a abordagem agressiva gera resistência ou atrito, por atacar a pessoa e não apontar a falha nem a solução. Metade: diz que "gera atrito", sem explicar o motivo. Zero: em branco, defende a abordagem agressiva, ou fora do tema.'),
      (v_atividade, 14, 2, 'Explique o que torna a abordagem construtiva baseada em parâmetros verificáveis.', 0.4, 'A abordagem construtiva se apoia em parâmetros verificáveis, como um valor de contraste medido e uma norma. Assim a crítica fala da tela, não de quem a criou, e foca na solução.', 'Nota cheia: explica que a crítica construtiva usa dados verificáveis e foca na solução, sem atacar a pessoa. Metade: cita apenas um dos dois pontos. Zero: em branco, ou fora do tema.'),
      (v_atividade, 14, 3, 'Reescreva a crítica de forma construtiva, com um dado mensurável e uma sugestão de solução.', 0.4, 'Uma reescrita válida é: "Notamos que o contraste de 2.1:1 dificulta a leitura. Sugiro elevar para 4.5:1 com este tom escuro."', 'Nota cheia: reescreve a crítica com dado mensurável (valor de contraste ou equivalente) e sugestão de solução concreta, sem tom de ataque. Metade: tem o dado ou a sugestão, mas não os dois. Zero: em branco, mantém o tom agressivo, ou fora do tema.'),
      (v_atividade, 15, 1, 'Explique o que significa criticar uma interface sem atacar quem a construiu.', 0.2, 'Criticar uma interface sem atacar quem a construiu é apontar a falha técnica com fatos e medidas, tratando o problema como da tela e não da pessoa.', 'Nota cheia: explica que a crítica foca na tela (falha técnica, fato ou medida) e não na pessoa autora. Metade: diz apenas "ser educado", sem ligar à falha técnica. Zero: em branco, ou fora do tema.'),
      (v_atividade, 15, 2, 'Explique por que apontar oportunidades técnicas com postura acolhedora favorece a solução em equipe.', 0.4, 'Uma postura acolhedora diminui a defensiva da equipe. Com menos resistência, as pessoas discutem as oportunidades técnicas e colaboram para encontrar a solução.', 'Nota cheia: explica que a postura acolhedora reduz a resistência e favorece a colaboração para a solução. Metade: diz que "é melhor para a equipe", sem explicar o mecanismo. Zero: em branco, ou fora do tema.'),
      (v_atividade, 15, 3, 'Descreva como você abriria a apresentação do seu diagnóstico para a equipe.', 0.4, 'A apresentação pode começar reconhecendo o esforço do trabalho feito pela equipe, depois mostrar os fatos medidos e, por fim, propor as melhorias em conjunto.', 'Nota cheia: descreve uma abertura com reconhecimento do trabalho, seguida de fatos medidos e de propostas em conjunto. Metade: descreve a abertura, mas sem a sequência ou sem as propostas. Zero: em branco, abertura agressiva, ou fora do tema.'),
      (v_atividade, 16, 1, 'Diga qual dado objetivo você pediria, como a taxa de desistência ou o tempo gasto na tarefa.', 0.2, 'O dado objetivo a pedir é a taxa de desistência da tarefa ou o tempo gasto para concluí-la, medidos na própria tela.', 'Nota cheia: indica um dado objetivo (taxa de desistência ou tempo gasto na tarefa) e o relaciona à tela. Metade: indica um dado objetivo sem relação com a tarefa, ou um dado vago ("mais acessos"). Zero: em branco, ou pede opinião da equipe, ou fora do tema.'),
      (v_atividade, 16, 2, 'Diga qual medição técnica você apresentaria para mostrar a violação de uma norma de acessibilidade.', 0.4, 'A medição técnica é o valor em pixels ou o índice de contraste que mostra a violação de uma norma de acessibilidade, por exemplo contraste abaixo de 4.5:1 ou área de toque menor que 44x44 px.', 'Nota cheia: indica uma medição concreta (pixels, índice de contraste ou área) comparada com a norma de acessibilidade. Metade: indica a medição, sem a comparação com a norma. Zero: em branco, ou medição de gosto pessoal, ou fora do tema.'),
      (v_atividade, 16, 3, 'Sugira uma alternativa viável que respeite a lógica do código já construído.', 0.4, 'Uma alternativa viável é ajustar a cor, o contraste ou o tamanho do botão já existente, sem reescrever o componente. Assim o código construído é aproveitado e a correção é pequena.', 'Nota cheia: propõe uma alteração pontual e viável (cor, contraste ou tamanho do elemento existente) que respeita o código já construído. Metade: propõe uma alternativa viável, sem explicar o respeito ao código existente. Zero: em branco, propõe redesenho total sem justificativa, ou fora do tema.'),
      (v_atividade, 17, 1, 'Explique o que verificar em contraste e legibilidade das fontes.', 0.2, 'Em contraste e legibilidade, verifique se todas as fontes atendem ao contraste mínimo exigido sobre os seus fundos.', 'Nota cheia: indica verificar se todas as fontes atendem ao contraste mínimo sobre o fundo. Metade: indica verificar a legibilidade, sem o contraste mínimo. Zero: em branco, ou fora do tema.'),
      (v_atividade, 17, 2, 'Explique o que verificar em áreas de toque e por que o tamanho mínimo importa.', 0.4, 'Em áreas de toque, verifique se botões e itens interativos têm pelo menos 44x44 pixels. O tamanho mínimo importa para que o dedo acerte o alvo e para evitar toques acidentais.', 'Nota cheia: indica verificar o mínimo de 44x44 px e explica que ele evita toques acidentais e permite acertar o alvo. Metade: indica o mínimo, sem explicar a importância. Zero: em branco, ou fora do tema.'),
      (v_atividade, 17, 3, 'Explique o que verificar em visibilidade da ação principal e em ruído visual.', 0.4, 'Em visibilidade da ação principal, verifique se a ação é evidente sem rolagem cega. Em ruído visual, verifique se há ícones decorativos ou bordas que poluem a hierarquia de leitura.', 'Nota cheia: indica o que verificar nos dois itens (ação principal visível sem rolagem cega; ícones ou bordas que poluem). Metade: cobre um dos dois itens corretamente. Zero: em branco, ou fora do tema.'),
      (v_atividade, 18, 1, 'Descreva como você leria a queixa e qual tela inspecionaria.', 0.2, 'Começo lendo a queixa com atenção e identifico a tela correspondente, por exemplo a tela de seleção de horário, para inspecioná-la.', 'Nota cheia: descreve a leitura da queixa e identifica a tela a inspecionar, ligando ao caso descrito. Metade: descreve a leitura, sem identificar a tela. Zero: em branco, ou pula para alterar o sistema, ou fora do tema.'),
      (v_atividade, 18, 2, 'Descreva quais parâmetros mediria na tela e como isolaria o defeito visual.', 0.4, 'Meço os parâmetros da tela (tamanho dos elementos, contraste, posição da ação) e isolo o defeito visual exato que gerou a queixa.', 'Nota cheia: indica medir parâmetros concretos e isolar o defeito visual específico. Metade: indica medir, sem isolar o defeito, ou o contrário. Zero: em branco, ou fora do tema.'),
      (v_atividade, 18, 3, 'Explique por que alterar o sistema sem esse caminho pode piorar o problema.', 0.4, 'Alterar o sistema sem diagnóstico pode piorar o problema, porque a mudança atinge um ponto que não é a causa, cria novos defeitos e torna a análise mais difícil.', 'Nota cheia: explica que alterar sem diagnóstico pode atingir o ponto errado, criar novos defeitos e dificultar a análise. Metade: diz apenas que "pode piorar", sem explicação. Zero: em branco, ou defende a alteração aleatória, ou fora do tema.'),
      (v_atividade, 19, 1, 'Defina causalidade e barreira, cada uma com as suas palavras.', 0.2, 'Causalidade é a relação técnica direta entre a falha de projeto e o bloqueio da ação. Barreira é o impedimento visual ou lógico que paralisa a conclusão da tarefa.', 'Nota cheia: define causalidade como relação técnica direta entre falha e bloqueio, e barreira como impedimento que paralisa a tarefa, com as próprias palavras. Metade: define um dos dois corretamente. Zero: em branco, ou definições trocadas, ou fora do tema.'),
      (v_atividade, 19, 2, 'Defina ruído visual e diagnóstico, cada um com as suas palavras.', 0.4, 'Ruído visual é o excesso de cores, linhas e elementos que sobrecarrega e polui a visão. Diagnóstico é a investigação formal de problemas de design com base em evidências verificáveis.', 'Nota cheia: define ruído visual como excesso de elementos que poluem a visão e diagnóstico como investigação formal com evidências verificáveis. Metade: define um dos dois corretamente. Zero: em branco, ou definições trocadas, ou fora do tema.'),
      (v_atividade, 19, 3, 'Explique a diferença entre barreira e ruído visual com um exemplo de cada.', 0.4, 'Barreira impede a pessoa de concluir a tarefa, como um botão fundido ao fundo que não se consegue acionar. Ruído visual apenas polui, como cinco cores de destaque competindo pela atenção, sem bloquear a ação.', 'Nota cheia: diferencia barreira (impede a conclusão) e ruído (polui sem necessariamente bloquear), com um exemplo de cada. Metade: diferencia, mas sem exemplo, ou com exemplo de um só. Zero: em branco, ou confunde os conceitos, ou fora do tema.'),
      (v_atividade, 20, 1, 'Explique a ideia de que "fatos provam", com base em medições reais.', 0.2, '"Fatos provam" significa que toda análise técnica começa em medições reais e verificáveis, e não em impressões.', 'Nota cheia: explica que a análise se apoia em medições reais e verificáveis, em vez de impressões. Metade: diz apenas que "fatos são importantes". Zero: em branco, ou fora do tema.'),
      (v_atividade, 20, 2, 'Explique a ideia de que "causas explicam", relacionando-a às decisões de layout ou estilo.', 0.4, '"Causas explicam" significa que decisões incorretas de layout ou estilo geram as barreiras. Exemplo: títulos e botões com o mesmo peso visual, que competem pela atenção e confundem a escolha.', 'Nota cheia: explica que decisões de layout ou estilo geram as barreiras e relaciona com um exemplo de decisão de layout ou estilo. Metade: explica a ideia, sem exemplo. Zero: em branco, ou fora do tema.'),
      (v_atividade, 20, 3, 'Explique a ideia de que "soluções libertam" e dê um exemplo de melhoria que remove atrito.', 0.4, '"Soluções libertam" significa que melhorias construtivas removem atritos e facilitam a vida da pessoa. Exemplo: aumentar o botão para 48 pixels e espaçar as datas em 8 pixels, para evitar toques errados.', 'Nota cheia: explica que a melhoria remove atrito e dá um exemplo concreto de melhoria que facilita o uso. Metade: explica a ideia, mas com exemplo genérico. Zero: em branco, ou fora do tema.');
end $$;
